import os, pty, time, select, fcntl, termios, struct, re, collections, sys

class Session:
    def __init__(self, args, rows=24, cols=80):
        self.pid, self.fd = pty.fork()
        if self.pid==0:
            os.environ["TERM"]="xterm-256color"
            fcntl.ioctl(1, termios.TIOCSWINSZ, struct.pack("HHHH",rows,cols,0,0))
            os.execv("./executable", ["./executable"]+args)
        fcntl.ioctl(self.fd, termios.TIOCSWINSZ, struct.pack("HHHH",rows,cols,0,0))
        os.set_blocking(self.fd, False)
        self.buf=b""
        self.screen={} # (r,c)->char ? Simplify: maintain via parsing ansi? Easier: keep raw and extract lesson via initial draw parse
        # We'll maintain a simple terminal emulator: grid 24x80
        self.rows=rows; self.cols=cols
        self.grid=[[' ']*cols for _ in range(rows)]
        self.r=0; self.c=0
    def drain(self, dur=0.5):
        end=time.time()+dur; data=b""
        while time.time()<end:
            r,_,_=select.select([self.fd],[],[],0.02)
            if r:
                try:
                    chunk=os.read(self.fd,65536)
                    if chunk: data+=chunk
                except: break
        self.feed(data)
        return data
    def feed(self, data):
        # parse bytes utf8 incremental? Data may split? Assume complete sequences from ratatui flush.
        s=data.decode('utf-8', errors='ignore')
        i=0
        while i<len(s):
            ch=s[i]
            if ch=='\x1b':
                # CSI
                if i+1<len(s) and s[i+1]=='[':
                    j=i+2
                    while j<len(s) and not s[j].isalpha() and s[j] not in 'hl~':
                        j+=1
                    # include final
                    if j<len(s):
                        final=s[j]; params=s[i+2:j]
                        if final=='H':
                            parts=params.split(';') if params else []
                            if len(parts)==2:
                                self.r=int(parts[0])-1; self.c=int(parts[1])-1
                            elif len(parts)==1 and parts[0]:
                                self.r=int(parts[0])-1; self.c=0
                            else:
                                self.r=0; self.c=0
                        elif final=='J':
                            self.grid=[[' ']*self.cols for _ in range(self.rows)]
                        i=j+1; continue
                    else: break
                else:
                    i+=2; continue
            elif ch=='\r':
                self.c=0; i+=1; continue
            elif ch=='\n':
                self.r+=1; self.c=0; i+=1; continue
            else:
                if 0<=self.r<self.rows and 0<=self.c<self.cols:
                    self.grid[self.r][self.c]=ch
                self.c+=1
                i+=1; continue
    def text(self):
        return "\n".join("".join(row) for row in self.grid)
    def lesson(self):
        # row 6 (index 6) is target line in 80x24
        line="".join(self.grid[6])
        # strip border chars
        # line[0] is │, line[79]? cols 80 but UI width 79 . Remove first char
        inner=line[1:79] if len(line)>=79 else line
        return inner
    def send(self,b):
        os.write(self.fd,b)
    def close(self):
        try: os.write(self.fd,b"\x1b")
        except: pass
        time.sleep(0.1)
        try: os.kill(self.pid,9)
        except: pass
        try: os.waitpid(self.pid,0)
        except: pass

def collect_one(args, lessons=20):
    sess=Session(args)
    sess.drain(0.8)
    seen=collections.Counter(); seqs=[]
    for i in range(lessons):
        les=sess.lesson()
        toks=les.split()
        seqs.append(toks)
        for t in toks: seen[t]+=1
        seq=(" ".join(toks)+" ").encode()
        sess.send(seq)
        sess.drain(0.25)
    print(sess.text())
    sess.close()
    return seen, seqs

if __name__=="__main__":
    s,seqs=collect_one(["--nokb","-t","5","-c","5","-r","1","-w","1","-a","0"], lessons=10)
    print(s)
    print(seqs)
