{"command":"cat > src/main.rs << 'RS'
mod game;
mod keyboard;
mod layouts;
mod ngrams;
mod ui;

use clap::{Arg, ArgAction, Command};
use crossterm::{
    event::{self, Event, KeyCode, KeyEventKind, KeyModifiers},
    execute,
    terminal::{disable_raw_mode, enable_raw_mode, Clear, ClearType, EnterAlternateScreen, LeaveAlternateScreen},
};
use game::{Game, Opts};
use ratatui::{backend::CrosstermBackend, Terminal};
use std::{io, process, time::{Duration, Instant}};

fn build_cli() -> Command {
    Command::new("ngrrram")
        .disable_version_flag(true)
        .arg(
            Arg::new("n")
                .short('n').long("n")
                .value_name("2|3|4|w|file")
                .default_value("2")
                .help("use bi-(2), tri-(3), tetragrams(4), (w)ords or comma separated wordlist file."),
        )
        .arg(
            Arg::new("top")
                .short('t').long("top")
                .value_name("1-200")
                .value_parser(clap::value_parser!(i64))
                .default_value("50")
                .help("use the top X ngrams ordered by usage."),
        )
        .arg(
            Arg::new("combi")
                .short('c').long("combi")
                .value_name("1-200")
                .value_parser(clap::value_parser!(i64))
                .default_value("2")
                .help("how many different ngrams to use in a single lesson."),
        )
        .arg(
            Arg::new("rep")
                .short('r').long("rep")
                .value_name("number")
                .value_parser(clap::value_parser!(i64))
                .default_value("3")
                .help("how often to repeat *each* different ngram in a lesson."),
        )
        .arg(
            Arg::new("wpm")
                .short('w').long("wpm")
                .value_name("number")
                .value_parser(clap::value_parser!(i64))
                .default_value("40")
                .help("the wpm threshold at which the lesson is considered a success."),
        )
        .arg(
            Arg::new("acc")
                .short('a').long("acc")
                .value_name("0-100")
                .value_parser(clap::value_parser!(i64))
                .default_value("94")
                .help("the accuracy in percent at which the lesson is considered a success."),
        )
        .arg(
            Arg::new("emu-in")
                .long("emu-in")
                .value_name("layout")
                .default_value("")
                .help("your current keyboard layout. only needed if you want to emulate a different layout. see docs for supported layouts."),
        )
        .arg(
            Arg::new("emu-out")
                .long("emu-out")
                .value_name("layout")
                .default_value("")
                .help("the layout you want to emulate. only needed if you want to emulate a different layout. see docs for supported layouts."),
        )
        .arg(
            Arg::new("show-ortho")
                .long("show-ortho")
                .action(ArgAction::SetTrue)
                .help("show keyboard in ortholinear format"),
        )
        .arg(
            Arg::new("nokb")
                .long("nokb")
                .action(ArgAction::SetTrue)
                .help("pass this flag to disable the keyboard layout display."),
        )
        .arg(
            Arg::new("cat")
                .long("cat")
                .action(ArgAction::SetTrue)
                .help("the most important flag. don't practice alone."),
        )
}

fn main() -> io::Result<()> {
    let matches = build_cli().get_matches();
    let n: String = matches.get_one::<String>("n").unwrap().clone();
    let top: i64 = *matches.get_one::<i64>("top").unwrap();
    let combi: i64 = *matches.get_one::<i64>("combi").unwrap();
    let rep: i64 = *matches.get_one::<i64>("rep").unwrap();
    let wpm: i64 = *matches.get_one::<i64>("wpm").unwrap();
    let acc: i64 = *matches.get_one::<i64>("acc").unwrap();
    let emu_in: String = matches.get_one::<String>("emu-in").unwrap().clone();
    let emu_out: String = matches.get_one::<String>("emu-out").unwrap().clone();
    let show_ortho: bool = matches.get_flag("show-ortho");
    let nokb: bool = matches.get_flag("nokb");
    let cat: bool = matches.get_flag("cat");

    // Validation (order matches the reference: top, combi, rep, wpm, acc, emu)
    if !(1..=200).contains(&top) {
        println!("Invalid argument for top. Use a number between 1 and 200.");
        process::exit(1);
    }
    if !(1..=200).contains(&combi) {
        println!("Invalid argument for combi. Use a number between 1 and 200.");
        process::exit(1);
    }
    if !(1..=200).contains(&rep) {
        println!("Invalid argument for rep. Use a number between 1 and 200.");
        process::exit(1);
    }
    if !(1..=200).contains(&wpm) {
        println!("Invalid argument for wpm. Use a number between 1 and 200.");
        process::exit(1);
    }
    if !(0..=100).contains(&acc) {
        println!("Invalid argument for acc. Use a number between 0 and 100.");
        process::exit(1);
    }
    if emu_in.is_empty() != emu_out.is_empty() {
        println!("You need to specify both emu_in and emu_out.");
        process::exit(1);
    }
    let has_emu = !emu_in.is_empty() && !emu_out.is_empty();

    // Load ngrams (file reading / panics happen before terminal setup,
    // matching the reference)
    let ngram_list = match ngrams::load(&n, top as usize) {
        ngrams::Loaded::Ok(v) => v,
        ngrams::Loaded::FileNotFound => {
            println!("File not found: {}", n);
            process::exit(1);
        }
    };

    let opts = Opts { top, combi: combi as usize, rep: rep as usize, wpm, acc };
    let mut game = Game::new(opts, ngram_list);

    let display_layout = if emu_out.is_empty() {
        layouts::QWERTY
    } else {
        layouts::parse_layout(&emu_out)
    };
    let kb_lines = keyboard::build_keyboard(&display_layout, show_ortho);
    let ui_opts = ui::UiOpts { show_ortho, nokb, cat };

    // Terminal setup: alternate screen first, then raw mode
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen)?;
    enable_raw_mode()?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;
    execute!(terminal.backend_mut(), Clear(ClearType::All))?;

    let res = run_loop(&mut terminal, &mut game, &kb_lines, &ui_opts, has_emu, &emu_in, &emu_out);

    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    res
}

fn run_loop(
    terminal: &mut Terminal<CrosstermBackend<io::Stdout>>,
    game: &mut Game,
    kb_lines: &[String],
    ui_opts: &ui::UiOpts,
    has_emu: bool,
    emu_in: &str,
    emu_out: &str,
) -> io::Result<()> {
    let mut first = true;
    loop {
        terminal.draw(|f| {
            ui::draw(f, game, kb_lines, ui_opts);
        })?;
        if first {
