                        game.check_lesson_completed();
                    }
                    KeyCode::Enter => {
                        if game.input.len() < game.cur_lesson.chars().count() {
                            game.input.push(' ');
                        }
                        game.check_lesson_completed();
                    }
                    KeyCode::Char(mut c) => {
                        if has_emu {
                            c = layouts::translate(c, emu_in, emu_out);
                        }
                        if c.is_alphabetic() || c == ' ' {
                            let target: Vec<char> = game.cur_lesson.chars().collect();
                            if game.input.len() < target.len() {
                                if !game.has_started {
