                                    game.time_started = Instant::now();
                                }
                                game.total_keys += 1;
                                if c != target[game.input.len()] {
                                    game.wrong += 1;
                                }
                                game.input.push(c);
                                game.check_lesson_completed();
                            }
                        }
                    }
                    _ => {}
                }
            }
        }
    }
    Ok(())
}
