use std::{io, process, time::{Duration, Instant}};

fn build_cli() -> Command {
    Command::new("ngrrram")
        .disable_version_flag(true)
        .arg(
            Arg::new("n")
                .short('n').long("n")
                .value_name("2|3|4|w|file")
