#[derive(Clone)]
pub struct UiOpts {
    pub show_ortho: bool,
    pub nokb: bool,
    pub cat: bool,
}

const CAT_ART: &[&str] = &[
    "          /\\_/\\        ",
    "         >(•༝• )<      ",
    "          |    \\       ",
    "          || |  )      ",
    "          ll-l-//      ",
    "/▔▔▔▔▔▔▔▔\\\\▔▔\\",
    "                        \\__>   ",
    "                         V",
];

fn centered(text_len: usize, area_width: u16) -> u16 {
    // start_col (1-based) of centered text inside the outer box [0,79)
    let inner_x = 1u16;
    let inner_w = 77u16;
    let _ = area_width;
    inner_x + (inner_w as usize).saturating_sub(text_len) as u16 / 2
}

pub fn draw(f: &mut Frame, game: &Game, kb_lines: &[String], opts: &UiOpts) {
    let size = f.area();
    // size gate: width <= 78 means "width < 79"
    let too_small = if opts.nokb {
        size.width <= 78 || size.height < 13
    } else {
        size.width <= 78 || size.height < 20
    };
    if too_small {
        let text = if opts.nokb {
            "Please resize your terminal to at least 80x13.\n<esc> or <ctrl-c> to quit"
        } else {
            "Please resize your terminal to at least 80x20,\nor consider disabling the keyboard display with --nokb\n\n<esc> or <ctrl-c> to quit"
        };
        let p = Paragraph::new(text).alignment(Alignment::Center);
        f.render_widget(p, size);
        return;
    }

    let box_w: u16 = 79;
    let box_h: u16 = if opts.nokb { 13 } else { 19 };
    let chunks_v = Layout::vertical([Constraint::Length(box_h), Constraint::Fill(1)]).split(size);
    let chunks_h = Layout::horizontal([Constraint::Length(box_w), Constraint::Fill(1)]).split(chunks_v[0]);
    let area = chunks_h[0];

    // Outer block with title
    let title_line = Line::from(vec![
        Span::raw("─ Quit "),
        Span::styled("<esc> ", Style::default().fg(Color::Blue).add_modifier(Modifier::BOLD)),
    ]);
    let block = Block::default()
        .borders(Borders::ALL)
        .border_type(BorderType::Rounded)
        .title(title_line.alignment(Alignment::Right));
    let inner = block.inner(area);
    f.render_widget(block, area);

    // Inner vertical layout
    let rows = if opts.nokb {
        vec![
            Constraint::Length(1), Constraint::Length(1), Constraint::Length(1), Constraint::Length(1),
            Constraint::Length(1), Constraint::Length(1), Constraint::Length(1), Constraint::Length(1),
            Constraint::Length(1), Constraint::Length(1), Constraint::Length(1),
        ]
    } else {
        vec![
            Constraint::Length(1), Constraint::Length(1), Constraint::Length(1), Constraint::Length(1),
            Constraint::Length(1), Constraint::Length(1), Constraint::Length(1),
            Constraint::Length(7),
            Constraint::Length(1), Constraint::Length(1), Constraint::Length(1),
        ]
    };
    let r = Layout::vertical(rows).split(inner);
    let (row_header, row_sep1, row_lesson, row_sep2, row_blank, row_target, row_wrong) =
        (r[0], r[1], r[2], r[3], r[4], r[5], r[6]);
    let _ = row_blank;
    let (row_sep3, row_stats1, row_stats2, kb_area_opt): (Rect, Rect, Rect, Option<Rect>) = if opts.nokb {
        (r[8], r[9], r[10], None)
    } else {
        (r[8], r[9], r[10], Some(r[7]))
    };

    // Header
    let header = Paragraph::new(Line::from(vec![
        Span::styled("               ngrrram!", Style::default().add_modifier(Modifier::BOLD)),
        Span::styled("   by winterveil", Style::default().fg(Color::Gray).add_modifier(Modifier::ITALIC)),
    ])).alignment(Alignment::Center);
    f.render_widget(header, row_header);

    // Separators
    let sep = "─".repeat(77);
    f.render_widget(Paragraph::new(sep.clone()), row_sep1);
    f.render_widget(Paragraph::new(sep.clone()), row_sep2);

    // Lesson line: left part + stats right-ish
    let left = format!("    Lesson #{}", game.lesson_num);
    let right_start = 63usize; // 0-based inside inner (col 64 absolute)
    let mut spans: Vec<Span> = Vec::new();
    let pad = right_start.saturating_sub(left.chars().count());
    spans.push(Span::raw(left));
    spans.push(Span::raw(" ".repeat(pad)));
    spans.push(Span::styled(format!("✔: {}, ", game.successes), Style::default().fg(Color::Green)));
    spans.push(Span::styled(format!("✘: {}    ", game.fails), Style::default().fg(Color::Red)));
    f.render_widget(Paragraph::new(Line::from(spans)), row_lesson);

    // Target (bold, per-char green/red/gray-bullet) + cursor
    let target_chars: Vec<char> = game.cur_lesson.chars().collect();
    let mut tspans: Vec<Span> = Vec::new();
    for (i, &tc) in target_chars.iter().enumerate() {
        let (sym, style) = if i < game.input.len() {
            if game.input[i] == tc {
                if tc == ' ' {
                    ("•".to_string(), Style::default().fg(Color::Gray).add_modifier(Modifier::BOLD))
                } else {
                    (tc.to_string(), Style::default().fg(Color::Green).add_modifier(Modifier::BOLD))
                }
            } else {
                if tc == ' ' {
                    ("•".to_string(), Style::default().fg(Color::Gray).add_modifier(Modifier::BOLD))
                } else {
                    (tc.to_string(), Style::default().fg(Color::Red).add_modifier(Modifier::BOLD))
                }
            }
        } else {
            (tc.to_string(), Style::default().add_modifier(Modifier::BOLD))
        };
        tspans.push(Span::styled(sym, style));
    }
    let target_para = Paragraph::new(Line::from(tspans)).alignment(Alignment::Center);
    f.render_widget(target_para, row_target);

    // Wrong row
    let mut wrong = String::new();
    for (i, &tc) in target_chars.iter().enumerate() {
        if i < game.input.len() && game.input[i] != tc {
            wrong.push(game.input[i]);
        } else {
            wrong.push(' ');
        }
    }
    let wrong_para = Paragraph::new(Line::from(Span::styled(wrong.clone(), Style::default().fg(Color::Gray).add_modifier(Modifier::ITALIC)))).alignment(Alignment::Center);
    f.render_widget(wrong_para, row_wrong);

    // Cursor position
    let text_len = target_chars.len();
    let start = centered(text_len, size.width);
    let cursor_x = start + game.input.len() as u16;
    f.set_cursor_position((cursor_x, area.y + 6));

    // Keyboard or blank
    if let Some(kb_area) = kb_area_opt {
        let kb_text = kb_lines.join("\n");
        let style = Style::default().fg(Color::Gray);
        if opts.cat {
            let sub = Layout::horizontal([Constraint::Fill(1), Constraint::Length(26)]).split(kb_area);
            // Left: keyboard truncated at sub[0] width
            let left_lines: Vec<Line> = kb_lines.iter().map(|l| {
                let t: String = l.chars().take(sub[0].width as usize).collect();
                Line::from(Span::styled(t, style))
            }).collect();
            f.render_widget(Paragraph::new(left_lines).alignment(Alignment::Center), sub[0]);
            // Right: cat lines 1.. (drop first, height 7 -> lines 1..=5 visible)
            let cat_lines: Vec<Line> = CAT_ART[1..].iter().map(|l| Line::raw(l.to_string())).collect();
            f.render_widget(Paragraph::new(cat_lines), sub[1]);
        } else {
            let kb_para = Paragraph::new(kb_text).style(style).alignment(Alignment::Center);
            f.render_widget(kb_para, kb_area);
        }
    }

    // Separator 3 (cat can overwrite part of it)
    if opts.cat && !opts.nokb {
        f.render_widget(Paragraph::new(sep.clone()), row_sep3);
        // overlay on kb_area (cat art rows 5,6 at kb rows 7,8) and stats rows
        if let Some(kb_area) = kb_area_opt {
            let sub = Layout::horizontal([Constraint::Fill(1), Constraint::Length(26)]).split(kb_area);
            let _ = sub;
        }
        // Draw cat separator/stats overlays by re-rendering merged lines below
    } else if !(opts.cat && opts.nokb) {
        f.render_widget(Paragraph::new(sep.clone()), row_sep3);
    }

    // Stats
    let gray = Style::default().fg(Color::Gray);
    let def = Style::default();
    let s1 = Line::from(vec![
        Span::styled(format!("  need >= {:>3}WPM,   avg. ", game.opts.wpm), gray),
        Span::styled(format!("{:>3}WPM", game.avg_wpm()), def),
        Span::styled(",   last", gray),
        Span::styled(format!("{:>4}WPM", game.last_wpm), def),
    ]);
    let s2 = Line::from(vec![
        Span::styled(format!("  need >= {:>3}% Acc, avg. ", game.opts.acc), gray),
        Span::styled(format!("{:>3}% Acc", game.avg_acc()), def),
        Span::styled(", last", gray),
        Span::styled(format!("{:>4}% Acc", game.last_acc), def),
    ]);
    f.render_widget(Paragraph::new(s1), row_stats1);
    f.render_widget(Paragraph::new(s2), row_stats2);

    // Cat overlays (rendered last, magenta in the reference)
    if opts.cat {
        let magenta = Style::default().fg(Color::Magenta);
        if !opts.nokb {
            if let Some(kb_area) = kb_area_opt {
                // rows below keyboard: separator row is kb_area.y+7 etc are handled via absolute rects
                let sep_overlay = Rect { x: area.x + 1 + 51, y: kb_area.y + 7, width: 26, height: 1 };
                let _ = sep_overlay;
                // CAT_ART[5] tail on separator, [6] on stats1, [7] char handled by buffer diff (skip)
                render_text_at(f, Rect { x: area.x + 62, y: row_sep3.y, width: 16, height: 1 }, "/▔▔▔▔▔▔▔▔\\\\▔▔\\", magenta);
                render_text_at(f, Rect { x: area.x + 70, y: row_stats1.y, width: 8, height: 1 }, "\\__>", magenta);
            }
        } else {
            // nokb+cat: art lines 0,1,2 on stats1, stats2, bottom border
            render_text_at(f, Rect { x: area.x + 52, y: row_stats1.y, width: 26, height: 1 }, CAT_ART[0], magenta);
            render_text_at(f, Rect { x: area.x + 52, y: row_stats2.y, width: 26, height: 1 }, CAT_ART[1], magenta);
            // bottom border row = area.y+12
            let bottom_y = area.y + 12;
            render_text_at(f, Rect { x: area.x + 52, y: bottom_y, width: 26, height: 1 }, CAT_ART[2], magenta);
            // Re-render separator-3 is already a normal sep row above stats; for nokb+cat the
            // reference keeps sep3 normal (row 9 of screen). It was skipped above, so draw it now:
            f.render_widget(Paragraph::new(sep.clone()), row_sep3);
            // Re-apply stats? No, cat overlays stats on the right, stats text is left part only - fine.
        }
    }
}

fn render_text_at(f: &mut Frame, rect: Rect, text: &str, style: Style) {
    let p = Paragraph::new(Line::from(Span::styled(text.to_string(), style)));
    f.render_widget(p, rect);
}
