use crate::game::Game;
use ratatui::{
    layout::{Alignment, Constraint, Layout, Rect},
    style::{Color, Modifier, Style},
    text::{Line, Span},
    widgets::{Block, BorderType, Borders, Paragraph},
    Frame,
};

#[derive(Clone)]
pub struct UiOpts {
    pub show_ortho: bool,
    pub nokb: bool,
    pub cat: bool,
}

const CAT_ART: &[&str] = &[
    "             /\\_/\\",
    "            >(•༝• )<",
    "             |    \\",
    "             || |  )",
    "             ll-l-//",
    "         /▔▔▔▔▔▔▔▔||▔▔\\",
    "                   \\__>",
    "                    V",
];

fn centered(text_len: usize) -> u16 {
    1 + (77usize.saturating_sub(text_len) / 2) as u16
}

pub fn draw(f: &mut Frame, game: &Game, kb_lines: &[String], opts: &UiOpts) {
    let size = f.area();
    let too_small = if opts.nokb {
        size.width <= 78 || size.height < 13
    } else {
        size.width <= 78 || size.height < 20
    };
    if too_small {
        let text = if opts.nokb {
            "Please resize your terminal to at least 80x13.\n<esc> or <ctrl-c> to quit"
        } else {
            "Please resize your terminal to at least 80x20,\nor consider disabling the keyboard display with --nokb\n\n<esc> or <ctrl-c> to quit"
        };
        let p = Paragraph::new(text).alignment(Alignment::Center);
        f.render_widget(p, size);
        return;
    }

    let box_w: u16 = 79;
    let box_h: u16 = if opts.nokb { 13 } else { 19 };
    let chunks_v = Layout::vertical([Constraint::Length(box_h), Constraint::Fill(1)]).split(size);
    let chunks_h = Layout::horizontal([Constraint::Length(box_w), Constraint::Fill(1)]).split(chunks_v[0]);
    let area = chunks_h[0];

    let title_line = Line::from(vec![
        Span::raw("─ Quit "),
        Span::styled("<esc> ", Style::default().fg(Color::Blue).add_modifier(Modifier::BOLD)),
    ]);
    let block = Block::default()
        .borders(Borders::ALL)
        .border_type(BorderType::Rounded)
        .title(title_line.alignment(Alignment::Right));
    let inner = block.inner(area);
    f.render_widget(block, area);

    let rows: Vec<Constraint> = if opts.nokb {
        (0..11).map(|_| Constraint::Length(1)).collect()
    } else {
        vec![
            Constraint::Length(1), Constraint::Length(1), Constraint::Length(1), Constraint::Length(1),
            Constraint::Length(1), Constraint::Length(1), Constraint::Length(1),
            Constraint::Length(7),
            Constraint::Length(1), Constraint::Length(1), Constraint::Length(1),
        ]
    };
    let r = Layout::vertical(rows).split(inner);
    let (row_header, row_sep1, row_lesson, row_sep2, row_target, row_wrong) = (r[0], r[1], r[2], r[3], r[5], r[6]);
    let (row_sep3, row_stats1, row_stats2, kb_row): (Rect, Rect, Rect, Option<Rect>) = if opts.nokb {
        (r[8], r[9], r[10], None)
    } else {
        (r[8], r[9], r[10], Some(r[7]))
    };

    // Cat (rendered before keyboard/stats; later widgets overwrite its
    // overflow, exactly like the reference)
    if opts.cat {
        let y = if opts.nokb { row_stats1.y } else { r[7].y + 2 };
        let cat_rect = Rect { x: area.x + 52, y, width: 26, height: 8 };
        let lines: Vec<Line> = CAT_ART.iter().map(|l| Line::raw(l.to_string())).collect();
        f.render_widget(Paragraph::new(lines), cat_rect);
    }

    // Header
    let header = Paragraph::new(Line::from(vec![
        Span::styled("               ngrrram!", Style::default().add_modifier(Modifier::BOLD)),
        Span::styled("   by winterveil", Style::default().fg(Color::Gray).add_modifier(Modifier::ITALIC)),
    ])).alignment(Alignment::Center);
    f.render_widget(header, row_header);

    let sep = "─".repeat(77);
    f.render_widget(Paragraph::new(sep.clone()), row_sep1);
    f.render_widget(Paragraph::new(sep.clone()), row_sep2);

    // Lesson line
    let left = format!("    Lesson #{}", game.lesson_num);
    let right_start = 63usize;
    let pad = right_start.saturating_sub(left.chars().count());
    let lesson_spans = vec![
        Span::raw(left),
        Span::raw(" ".repeat(pad)),
        Span::styled(format!("✔: {}, ", game.successes), Style::default().fg(Color::Green)),
        Span::styled(format!("✘: {}    ", game.fails), Style::default().fg(Color::Red)),
    ];
    f.render_widget(Paragraph::new(Line::from(lesson_spans)), row_lesson);

    // Target
    let target_chars: Vec<char> = game.cur_lesson.chars().collect();
    let mut tspans: Vec<Span> = Vec::new();
    for (i, &tc) in target_chars.iter().enumerate() {
        let (sym, style) = if i < game.input.len() {
            if tc == ' ' {
                // typed space (correct or not) is shown as a gray bullet
                ("•".to_string(), Style::default().fg(Color::Gray).add_modifier(Modifier::BOLD))
            } else if game.input[i] == tc {
                (tc.to_string(), Style::default().fg(Color::Green).add_modifier(Modifier::BOLD))
            } else {
                (tc.to_string(), Style::default().fg(Color::Red).add_modifier(Modifier::BOLD))
            }
        } else {
            (tc.to_string(), Style::default().add_modifier(Modifier::BOLD))
        };
        tspans.push(Span::styled(sym, style));
    }
    f.render_widget(Paragraph::new(Line::from(tspans)).alignment(Alignment::Center), row_target);

    // Wrong row
    let mut wrong = String::new();
    for (i, &tc) in target_chars.iter().enumerate() {
        if i < game.input.len() && game.input[i] != tc {
            wrong.push(game.input[i]);
        } else {
            wrong.push(' ');
        }
    }
    let wrong_para = Paragraph::new(Line::from(Span::styled(wrong, Style::default().fg(Color::Gray).add_modifier(Modifier::ITALIC)))).alignment(Alignment::Center);
    f.render_widget(wrong_para, row_wrong);

    // Cursor
    let cursor_x = centered(target_chars.len()) + game.input.len() as u16;
    f.set_cursor_position((area.x + cursor_x, area.y + 6));

    // Keyboard (hardcoded geometry matching the reference)
    if let Some(kb) = kb_row {
        let gray = Style::default().fg(Color::Gray);
        let lines: Vec<Line> = kb_lines.iter().map(|l| Line::from(Span::styled(l.clone(), gray))).collect();
        let rect = if opts.cat {
            Rect { x: area.x + 6, y: kb.y, width: 55, height: 7 }
        } else {
            Rect { x: area.x + 14, y: kb.y, width: 64, height: 7 }
        };
        let para = Paragraph::new(lines).style(gray);
        f.render_widget(para, rect);
    }

    // Separator before stats; for --cat (with keyboard) the reference
    // merges the cat blanket into this separator.
    if opts.cat && !opts.nokb {
        let merged = format!("{}{}───", "─".repeat(60), CAT_ART[5].trim_start());
        // CAT_ART[5] trimmed is 14 wide: 60 + 14 + 3 = 77
        f.render_widget(Paragraph::new(merged), row_sep3);
    } else {
        f.render_widget(Paragraph::new(sep.clone()), row_sep3);
    }

    // Stats
    let gray = Style::default().fg(Color::Gray);
    let def = Style::default();
    let s1 = Line::from(vec![
        Span::styled(format!("  need >= {:>3}WPM,   avg. ", game.opts.wpm), gray),
        Span::styled(format!("{:>3}WPM", game.avg_wpm()), def),
        Span::styled(",   last", gray),
        Span::styled(format!("{:>4}WPM", game.last_wpm), def),
    ]);
    let s2 = Line::from(vec![
        Span::styled(format!("  need >= {:>3}% Acc, avg. ", game.opts.acc), gray),
        Span::styled(format!("{:>3}% Acc", game.avg_acc()), def),
        Span::styled(", last", gray),
        Span::styled(format!("{:>4}% Acc", game.last_acc), def),
    ]);
    f.render_widget(Paragraph::new(s1), row_stats1);
    f.render_widget(Paragraph::new(s2), row_stats2);

    // Bottom border needs redrawing over the cat in nokb+cat mode
    // (its third line sits on the border row)
    if opts.cat && opts.nokb {
        let bottom_y = area.y + 12;
        let bottom = format!("╰{}╯", "─".repeat(77));
        f.render_widget(Paragraph::new(bottom), Rect { x: area.x, y: bottom_y, width: 79, height: 1 });
        // re-apply cat line on the border
        let cat_rect = Rect { x: area.x + 52, y: bottom_y, width: 26, height: 1 };
        f.render_widget(Paragraph::new(Line::raw(CAT_ART[2].to_string())), cat_rect);
    }
}
