// A Crossterm backend whose `draw` emits foreground/background color
// changes as separate SGR sequences (the style used by older ratatui
// versions), instead of the combined SetColors sequence.
use crossterm::{
    cursor::{Hide, MoveTo, Show},
    execute, queue,
    style::{Attribute as CAttribute, Color as CColor, Print, SetAttribute, SetBackgroundColor, SetForegroundColor, SetUnderlineColor},
    terminal::{self, ClearType as CClearType},
};
use ratatui::{
    backend::{Backend, ClearType, WindowSize},
    buffer::Cell,
    layout::{Position, Size},
    style::{Color, Modifier},
};
use std::io::{self, Write};

pub struct MyBackend<W: Write> {
    writer: W,
}

impl<W: Write> MyBackend<W> {
    pub fn new(writer: W) -> Self { Self { writer } }
    pub fn writer_mut(&mut self) -> &mut W { &mut self.writer }
}

fn to_crossterm(c: Color) -> CColor {
    match c {
        Color::Reset => CColor::Reset,
        Color::Black => CColor::Black,
        Color::Red => CColor::DarkRed,
        Color::Green => CColor::DarkGreen,
        Color::Yellow => CColor::DarkYellow,
        Color::Blue => CColor::DarkBlue,
        Color::Magenta => CColor::DarkMagenta,
        Color::Cyan => CColor::DarkCyan,
        Color::Gray => CColor::Grey,
        Color::DarkGray => CColor::DarkGrey,
        Color::LightRed => CColor::Red,
        Color::LightGreen => CColor::Green,
        Color::LightBlue => CColor::Blue,
        Color::LightYellow => CColor::Yellow,
        Color::LightMagenta => CColor::Magenta,
        Color::LightCyan => CColor::Cyan,
        Color::White => CColor::White,
        Color::Indexed(i) => CColor::AnsiValue(i),
        Color::Rgb(r, g, b) => CColor::Rgb { r, g, b },
    }
}

struct ModifierDiff { from: Modifier, to: Modifier }
impl ModifierDiff {
    fn queue<W: Write>(&self, mut w: W) -> io::Result<()> {
        let removed = self.from - self.to;
        if removed.contains(Modifier::REVERSED) {
            queue!(w, SetAttribute(CAttribute::NoReverse))?;
        }
        let reset_intensity = removed.contains(Modifier::BOLD) || removed.contains(Modifier::DIM);
        if reset_intensity {
            queue!(w, SetAttribute(CAttribute::NormalIntensity))?;
            if self.to.contains(Modifier::DIM) { queue!(w, SetAttribute(CAttribute::Dim))?; }
            if self.to.contains(Modifier::BOLD) { queue!(w, SetAttribute(CAttribute::Bold))?; }
        }
        if removed.contains(Modifier::ITALIC) { queue!(w, SetAttribute(CAttribute::NoItalic))?; }
        if removed.contains(Modifier::UNDERLINED) { queue!(w, SetAttribute(CAttribute::NoUnderline))?; }
        if removed.contains(Modifier::CROSSED_OUT) { queue!(w, SetAttribute(CAttribute::NotCrossedOut))?; }
        if removed.contains(Modifier::HIDDEN) { queue!(w, SetAttribute(CAttribute::NoHidden))?; }
        if removed.contains(Modifier::SLOW_BLINK) || removed.contains(Modifier::RAPID_BLINK) {
            queue!(w, SetAttribute(CAttribute::NoBlink))?;
        }
        let added = self.to - self.from;
        if added.contains(Modifier::REVERSED) { queue!(w, SetAttribute(CAttribute::Reverse))?; }
        if added.contains(Modifier::BOLD) && !reset_intensity { queue!(w, SetAttribute(CAttribute::Bold))?; }
        if added.contains(Modifier::ITALIC) { queue!(w, SetAttribute(CAttribute::Italic))?; }
        if added.contains(Modifier::UNDERLINED) { queue!(w, SetAttribute(CAttribute::Underlined))?; }
        if added.contains(Modifier::DIM) && !reset_intensity { queue!(w, SetAttribute(CAttribute::Dim))?; }
        if added.contains(Modifier::CROSSED_OUT) { queue!(w, SetAttribute(CAttribute::CrossedOut))?; }
        if added.contains(Modifier::HIDDEN) { queue!(w, SetAttribute(CAttribute::Hidden))?; }
        if added.contains(Modifier::SLOW_BLINK) { queue!(w, SetAttribute(CAttribute::SlowBlink))?; }
        if added.contains(Modifier::RAPID_BLINK) { queue!(w, SetAttribute(CAttribute::RapidBlink))?; }
        Ok(())
    }
}

impl<W: Write> Backend for MyBackend<W> {
    type Error = io::Error;

    fn draw<'a, I>(&mut self, content: I) -> io::Result<()>
    where I: Iterator<Item = (u16, u16, &'a Cell)>
    {
        let mut fg = Color::Reset;
        let mut bg = Color::Reset;
        let mut underline_color = Color::Reset;
        let mut modifier = Modifier::empty();
        let mut last_pos: Option<Position> = None;
        for (x, y, cell) in content {
            if !matches!(last_pos, Some(p) if x == p.x + 1 && y == p.y) {
                queue!(self.writer, MoveTo(x, y))?;
            }
            last_pos = Some(Position { x, y });
            if cell.modifier != modifier {
                let diff = ModifierDiff { from: modifier, to: cell.modifier };
                diff.queue(&mut self.writer)?;
                modifier = cell.modifier;
            }
            if cell.fg != fg {
                queue!(self.writer, SetForegroundColor(to_crossterm(cell.fg)))?;
                fg = cell.fg;
            }
            if cell.bg != bg {
                queue!(self.writer, SetBackgroundColor(to_crossterm(cell.bg)))?;
                bg = cell.bg;
            }
            if cell.underline_color != underline_color {
                queue!(self.writer, SetUnderlineColor(to_crossterm(cell.underline_color)))?;
                underline_color = cell.underline_color;
            }
            queue!(self.writer, Print(cell.symbol()))?;
        }
        queue!(
            self.writer,
            SetForegroundColor(CColor::Reset),
            SetBackgroundColor(CColor::Reset),
            SetUnderlineColor(CColor::Reset),
            SetAttribute(CAttribute::Reset),
        )
    }

    fn hide_cursor(&mut self) -> io::Result<()> { execute!(self.writer, Hide) }
    fn show_cursor(&mut self) -> io::Result<()> { execute!(self.writer, Show) }
    fn get_cursor_position(&mut self) -> io::Result<Position> {
        crossterm::cursor::position().map(|(x, y)| Position { x, y }).map_err(io::Error::other)
    }
    fn set_cursor_position<P: Into<Position>>(&mut self, position: P) -> io::Result<()> {
        let Position { x, y } = position.into();
        execute!(self.writer, MoveTo(x, y))
    }
    fn clear(&mut self) -> io::Result<()> { self.clear_region(ClearType::All) }
    fn clear_region(&mut self, clear_type: ClearType) -> io::Result<()> {
        execute!(self.writer, terminal::Clear(match clear_type {
            ClearType::All => CClearType::All,
            ClearType::AfterCursor => CClearType::FromCursorDown,
            ClearType::BeforeCursor => CClearType::FromCursorUp,
            ClearType::CurrentLine => CClearType::CurrentLine,
            ClearType::UntilNewLine => CClearType::UntilNewLine,
        }))
    }
    fn size(&self) -> io::Result<Size> {
        let (width, height) = terminal::size()?;
        Ok(Size { width, height })
    }
    fn window_size(&mut self) -> io::Result<WindowSize> {
        let ws = terminal::window_size()?;
        Ok(WindowSize {
            columns_rows: Size { width: ws.columns, height: ws.rows },
            pixels: Size { width: ws.width, height: ws.height },
        })
    }
    fn flush(&mut self) -> io::Result<()> { self.writer.flush() }
}
